/* ── los datos ───────────────────────────────────────────────────── */
function quimCtrlDeH(cod){
  for(var i = 0; i < QUIM_CTRL.length; i++) if(QUIM_CTRL[i].h.indexOf(cod) > -1) return QUIM_CTRL[i];
  return null;
}
/* las frases H del producto, juntadas por grupo y en el orden del SGA:
   [{g:grupo, h:['H225']}, {g:…, h:['H350','H361']}] */
function quimGrupos(hs){
  var por = {}, out = [], sueltas = [];
  (hs || []).forEach(function(cod){
    var g = quimCtrlDeH(cod);
    /* una frase que no está en ningún grupo sale igual, sin control
       inventado */
    if(!g){ if(sueltas.indexOf(cod) < 0) sueltas.push(cod); return; }
    if(!por[g.k]){ por[g.k] = { g:g, h:[] }; }
    if(por[g.k].h.indexOf(cod) < 0) por[g.k].h.push(cod);
  });
  QUIM_CTRL.forEach(function(g){ if(por[g.k]){ por[g.k].h.sort(); out.push(por[g.k]); } });
  if(sueltas.length) out.push({ g:{ k:'otras', h:sueltas, cuida:'', sipasa:'', epp:[], proh:[] }, h:sueltas.sort() });
  return out;
}
function _quimItem(k){
  var i;
  for(i = 0; i < QUIM_EPP.length; i++) if(QUIM_EPP[i].k === k) return QUIM_EPP[i];
  for(i = 0; i < QUIM_PROH.length; i++) if(QUIM_PROH[i].k === k) return QUIM_PROH[i];
  return null;
}
function _quimEsProh(k){ for(var i = 0; i < QUIM_PROH.length; i++) if(QUIM_PROH[i].k === k) return true; return false; }
/* lo sugerido por las frases H: EPP y prohibiciones, en el orden de las listas */
function quimEppSugerido(hs){
  var ya = {};
  quimGrupos(hs).forEach(function(x){ x.g.epp.concat(x.g.proh).forEach(function(k){ ya[k] = 1; }); });
  var out = [];
  QUIM_EPP.concat(QUIM_PROH).forEach(function(it){ if(ya[it.k]) out.push(it.k); });
  return out;
}
/* lo que va en ESE producto: lo ajustado por el supervisor o, si nadie
   lo tocó, lo sugerido */
function quimEppDe(sga){
  sga = sga || {};
  if(Array.isArray(sga.epp)) return sga.epp.filter(function(k){ return !!_quimItem(k); });
  return quimEppSugerido(sga.h || []);
}
function quimEppLimpio(v){
  if(!Array.isArray(v)) return null;
  var ya = {}, out = [];
  QUIM_EPP.concat(QUIM_PROH).forEach(function(it){ if(v.indexOf(it.k) > -1 && !ya[it.k]){ ya[it.k] = 1; out.push(it.k); } });
  return out;
}
/* para el QR y el anexo de la nota: una letra por cosa. «-» es «nada»
   (el supervisor sacó todo a propósito, que no es lo mismo que «nadie
   lo tocó»). */
function quimEppCodigo(v){
  if(!Array.isArray(v)) return '';
  var s = v.map(function(k){ var it = _quimItem(k); return it ? it.c : ''; }).join('');
  return s || '-';
}
function quimEppDeCodigo(s){
  if(s === undefined || s === null || s === '') return null;
  s = String(s);
  if(s === '-') return [];
  var out = [];
  for(var i = 0; i < s.length; i++){
    var ch = s.charAt(i);
    QUIM_EPP.concat(QUIM_PROH).forEach(function(it){ if(it.c === ch && out.indexOf(it.k) < 0) out.push(it.k); });
  }
  return quimEppLimpio(out);
}
function _quimSenal(k){
  var it = _quimItem(k); if(!it || typeof NTP_SENALES === 'undefined') return null;
  for(var i = 0; i < NTP_SENALES.length; i++) if(NTP_SENALES[i].k === it.s) return NTP_SENALES[i];
  return null;
}
function quimSenalSVG(k, tam){
  var s = _quimSenal(k), it = _quimItem(k);
  if(!s) return '';
  /* con su fondo blanco, como impresa: la de prohibido es transparente
     por dentro, y sobre la pantalla oscura el dibujo negro no se veía */
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="' + tam + '" height="' + tam +
         '" role="img" aria-label="' + escA(it ? it.n : '') + '"><circle cx="50" cy="50" r="49" fill="#fff"/>' + s.s + '</svg>';
}

