  solinfl:   ['Lejos de llamas y chispas; no fumes.', 'Si hay fuego: el extintor de la hoja MSDS.'],
  autorreac: ['Fresco, lejos del calor y separado.', 'Si hay fuego: evacúa la zona.'],
