/* el rombo NFPA, solo si la hoja lo trae escrito con sus números */
function _qlRombo(texto){
  var re = /NFPA/gi, m;
  while((m = re.exec(texto))){
    /* «NFPA 704» es el nombre de la norma, no un número del rombo */
    var v = texto.slice(m.index, m.index + 320).replace(/^NFPA\s*704\b/i, 'NFPA');
    var s = v.match(/(salud|health|sanidad)[^0-9\n]{0,24}([0-4])(?!\d)/i),
        i = v.match(/(inflamabilidad|flamabilidad|flammability|fire|fuego|incendio)[^0-9\n]{0,24}([0-4])(?!\d)/i),
        r = v.match(/(reactividad|inestabilidad|reactivity|instability)[^0-9\n]{0,24}([0-4])(?!\d)/i);
    var o = null;
    if(s && i && r) o = {s:+s[2], i:+i[2], r:+r[2], e:''};
    else {
      var t3 = v.match(/NFPA[^0-9\n]{0,24}([0-4])\s*[-–\/]\s*([0-4])\s*[-–\/]\s*([0-4])(?!\d)/i);
      if(t3) o = {s:+t3[1], i:+t3[2], r:+t3[3], e:''};
    }
    if(!o) continue;
    var e = v.match(/(especial|special|otros|riesgo\s+espec[ií]fico)[^A-Za-z0-9\n]{0,12}(OX|OXY|W|SA)\b/i);
    if(e) o.e = /^OX/i.test(e[2]) ? 'OX' : e[2].toUpperCase();
    return o;
  }
  return null;
}
function _qlLimpiarValor(v){
  v = String(v || '').split('\n')[0];
  v = v.split(/\s{3,}|\s+(c[oó]digo|uso|usos|sin[oó]nimos?|otros\s+medios|n[uú]mero|referencia|versi[oó]n|fecha|revisi[oó]n|direcci[oó]n|domicilio|tel[eé]fono|tel\.|ruc|e-?mail|correo|web|address|phone|product\s+code|recommended)\b/i)[0];
  /* el punto final se queda («S.A.C.»): solo se quitan los separadores */
  v = v.replace(/^[\s:.\-–—]+|[\s:\-–—]+$/g, '').replace(/\s+/g, ' ');
  return (v.length >= 2 && v.length <= 90 && /[A-Za-zÁÉÍÓÚÑáéíóúñ]/.test(v)) ? v : '';
}
function _qlCampo(t, re){ var m = t.match(re); return m ? _qlLimpiarValor(m[m.length - 1]) : ''; }

/* ══ LO QUE SE ENCONTRÓ ══
   {texto: cuántas letras, sec2: si se halló la sección 2, n, m, h[], pp[],
    p[], sw, nf} */
function quimLeerTexto(texto){
  texto = String(texto || '').replace(/\r/g, '').replace(/[   ]/g, ' ');
  var r = {texto:texto.replace(/\s+/g, '').length, sec2:false, n:'', m:'', h:[], pp:[], p:[], sw:'', nf:null};
  if(r.texto < 60) return r;
  var s2 = _qlSeccion2(texto), base = s2 ? s2.texto : texto;
  r.sec2 = !!s2;
  r.h = _qlCodigosH(base);
  r.pp = _qlCodigosP(base);
  var gp = [], rg = /(^|[^A-Za-z0-9])(GHS|SGA)\s?0?([1-9])(?!\d)/g, mg;
  while((mg = rg.exec(base))){ var k = 'GHS0' + mg[3]; if(gp.indexOf(k) < 0) gp.push(k); }
  var ph = quimPictosDeH(r.h);
  r.p = ph.concat(gp.filter(function(k){ return ph.indexOf(k) < 0; })).sort();
  r.sw = _qlPalabra(base) || quimPalabraDeH(r.h);
  r.nf = _qlRombo(texto);
  var s1 = texto.slice(0, s2 ? s2.ini : Math.min(texto.length, 3000));
  r.n = _qlCampo(s1, /(nombre\s+(comercial\s+)?del\s+producto|nombre\s+comercial|nombre\s+de\s+la\s+(sustancia|mezcla)|identificador\s+del\s+producto|denominaci[oó]n|product\s+name|trade\s+name|product\s+identifier)\s*[:.\-]?\s*([^\n]{2,120})/i);
  r.m = _qlCampo(s1, /(fabricante|proveedor|nombre\s+del\s+proveedor|distribuidor|importador|raz[oó]n\s+social|manufacturer|supplier|company\s+name)\s*[:.\-]?\s*([^\n]{2,120})/i);
  return r;
}

/* ── pdf.js, pedido recién cuando hace falta ───────────────────────── */
var QUIM_PDFJS_BASE = 'pdfjs/', QUIM_PDFJS_VER = '6.3.289', _QL_PDFJS = null;
function quimPdfjs(){
  if(_QL_PDFJS) return _QL_PDFJS;
  var u = function(f){ return new URL(QUIM_PDFJS_BASE + f + '?v=' + QUIM_PDFJS_VER, location.href).href; };
  _QL_PDFJS = import(u('pdf.min.mjs')).then(function(m){
    m.GlobalWorkerOptions.workerSrc = u('pdf.worker.min.mjs');
    return m;
  });
  _QL_PDFJS.catch(function(){ _QL_PDFJS = null; });
  return _QL_PDFJS;
}
/* el texto de las primeras 20 páginas. Error: 'clave' (tiene contraseña),
   'no_pdf' (no es un PDF que se pueda abrir), 'sin_lector' (el navegador
   no pudo cargar pdf.js) */
function quimLeerPDF(blob){
  return quimPdfjs().catch(function(){ return Promise.reject('sin_lector'); }).then(function(pdfjs){
    return blob.arrayBuffer().then(function(buf){
      return pdfjs.getDocument({data:new Uint8Array(buf), isEvalSupported:false, disableFontFace:true, stopAtErrors:false}).promise;
    }).catch(function(e){
      return Promise.reject(e && /password/i.test(String(e.name || e.message || '')) ? 'clave' : 'no_pdf');
    }).then(function(doc){
      var n = Math.min(doc.numPages || 0, 20), partes = [], cad = Promise.resolve();
      for(var i = 1; i <= n; i++) (function(i){
        cad = cad.then(function(){ return doc.getPage(i); }).then(function(pg){ return pg.getTextContent(); })
                 .then(function(tc){ partes.push(_qlTextoDe(tc.items)); }, function(){ partes.push(''); });
      })(i);
      return cad.then(function(){
        var r = {texto:partes.join('\n'), paginas:doc.numPages || 0};
        try{ doc.destroy(); }catch(_d){}
        return r;
      });
    });
  });
}
